package com.wizzadrds.theworldremembers.behavior; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import net.minecraft.core.BlockPos; import java.util.UUID; class NpcTravelStateTest{@Test void travelUsesObservedDistanceAndElapsedTime(){var id=UUID.randomUUID();var s=new NpcTravelState(id,new BlockPos(0,0,0),new BlockPos(10,0,0),100,100,0).observe(new BlockPos(6,0,8),140);assertEquals(100,s.distance());assertEquals(40,s.elapsed(140));}}